## BERTopic (bt) metrics
# The following functions are used to evaluate the quality of topics generated by BERTopic
#
# Topic coherence: is a measure of how interpretable and coherent the topics are.
# - bt_topic_coherence_npmi: NPMI coherence
# - bt_topic_coherence_c_v: C_V coherence
#
# Topic Diversity: is a measure of how different the topics are from each other.
# - bt_proportion_unique_words: Proportion of unique words
# - bt_pairwise_jaccard_diversity: Pairwise Jaccard diversity
# (Confer for examples and explanation of Topic Diversity, plus where this code is adapted from: [silviatti/topic-model-diversity: A collection of topic diversity measures for topic modeling](https://github.com/silviatti/topic-model-diversity/tree/master))

####
## Helper functions
####


def get_topic_words_bertopic(topic_model, topics):
    # Get topic words: a list of lists of (topic representing) words for each topic
    topic_words = [
        [words for words, _ in topic_model.get_topic(topic)]
        for topic in range(len(set(topics)) - 1)
    ]

    return topic_words


def get_top_n_topic_words_lda(model, num_words=10):
    """
    Extract the top N words from each topic in a Gensim topic model.

    Parameters:
    - model: Gensim topic model (e.g., LdaModel or HdpModel).
    - num_words: Number of top words to retrieve per topic.

    Returns:
    - List of lists containing top words for each topic.
    """
    topics = model.show_topics(num_topics=-1, num_words=num_words, formatted=False)
    top_words_per_topic = [[word for word, _ in topic_words] for _, topic_words in topics]
    return top_words_per_topic


def process_topic_words(topic_words, dictionary):
    """
    Preprocess topic words to align with standard preprocessing for coherence evaluation.
    """
    print("Original topic words:")
    print(topic_words)

    pp = preprocessing.TextPreprocessor()
    pp_topic_words = pp.process_topic_words(topic_words)
    # Filter topic words to only include words that are in the dictionary
    pp_topic_words = [
        [word for word in topic if word in dictionary.token2id] for topic in pp_topic_words
    ]

    print("Preprocessed topic words:")
    print(pp_topic_words)

    # Check if preprocessed topic words have the same length as original topic words, print warning if not
    for sublist1, sublist2 in zip(topic_words, pp_topic_words):
        if len(sublist1) != len(sublist2):
            print(
                "WARNING from metrics.py@evaluate_bt_model: Preprocessed topic words have different length than original topic words, likely because you have stopwords in your topic words that have been removed in preprocessing. Preprocessing is done to match standard preprocessing used for Coherence metrics."
            )
            print(
                f"Topic with {len(sublist1)} words, that was processed to have {len(sublist2)} words: Topic: {sublist1} ; Processed topic: {sublist2}"
            )
            unique_words = set(sublist1) ^ set(sublist2)
            print("Words in only one list:", unique_words)
    return pp_topic_words


# TODO: only works if all metrics are calculated
def create_metrics_dataframe(metric_dict) -> pd.DataFrame:
    """
    Creates a Pandas DataFrame from the metric dictionary.

    Args:
        metric_dict (dict): Dictionary containing the metrics.

    Returns:
        pd.DataFrame: Pandas DataFrame representing the metrics.
    """
    data = []
    data.append(["Topic Coherence", "C_NPMI", metric_dict["C_NPMI"]])
    data.append(["Topic Coherence", "C_V", metric_dict["C_V"]])
    data.append(["Topic Diversity", "Proportion of unique words", metric_dict["D_PROP_UNI_WORDS"]])
    data.append(["Topic Diversity", "Pairwise Jaccard distance", metric_dict["D_PAIR_JAC_DIST"]])
    data.append(["External Clustering Metrics", "Purity", metric_dict["EXT_P1"]])
    data.append(["External Clustering Metrics", "Adjusted Rand Index", metric_dict["EXT_ARI"]])
    data.append(
        ["External Clustering Metrics", "Normalized Mutual Information", metric_dict["EXT_NMI"]]
    )
    data.append(["Internal Clustering Metrics", "Silhouette Score", metric_dict["INT_SILHOUETTE"]])
    data.append(
        ["Internal Clustering Metrics", "Davies-Bouldin Score", metric_dict["INT_DAVIES_BOULDIN"]]
    )
    data.append(
        [
            "Internal Clustering Metrics",
            "Calinski-Harabasz Score",
            metric_dict["INT_CALINSKI_HARABASZ"],
        ]
    )
    data.append(
        ["LLM Usefulness", "U_LLM_USEFULNESS score", metric_dict["U_LLM_USEFULNESS"]["U_score"]]
    )

    df = pd.DataFrame(data, columns=["Section", "Metric Name", "Value"])

    # Format the 'Value' column to 3 decimal places (except for LLM score which is 2)
    df["Value"] = df.apply(
        lambda row: f"{row['Value']:.3f}"
        if row["Metric Name"] != "U_LLM_USEFULNESS score"
        else f"{row['Value']:.2f}",
        axis=1,
    )
    return df


