def bt_topic_coherence_npmi(topic_words, texts, corpus, dictionary):
    """
    compute the NPMI coherence of the topics

    Parameters
    ----------
    docs: list of documents
    topic_model: BERTopic model
    topics: the list of topics (topic ids) for each document as BERTopic transform/fit_transform outputs it
    """

    # Assign topics to documents
    # topics, _ = topic_model.transform(docs)

    # Test print all intuts to coherence model
    # print("topic_words: ", topic_words[0])
    # print("texts: ", texts[0])
    # print("corpus: ", corpus[0])
    # print("dictionary: ", dictionary)

    # Evaluate Coherence
    coherence_model = CoherenceModel(
        topics=topic_words,
        texts=tqdm(texts),
        corpus=corpus,
        dictionary=dictionary,
        coherence="c_npmi",
        topn=10,
    )
    coherence = coherence_model.get_coherence()

    return coherence


def bt_topic_coherence_npmi_per_topic(topic_words, texts, corpus, dictionary):
    """
    Compute the NPMI coherence score for each topic individually.

    Parameters
    ----------
    topic_words : List[List[str]]
        A list where each element is a list of words representing a topic.
    texts : List[List[str]]
        Tokenized texts used for evaluation.
    corpus : List[List[Tuple[int, int]]]
        The corpus in Bag-of-Words (BoW) format.
    dictionary : gensim.corpora.dictionary.Dictionary
        The dictionary mapping of word IDs to words.

    Returns
    -------
    coherences : List[float]
        A list of NPMI coherence scores for each topic.
    """
    # Evaluate Coherence per topic
    coherence_model = CoherenceModel(
        topics=topic_words,
        texts=tqdm(texts),
        corpus=corpus,
        dictionary=dictionary,
        coherence="c_npmi",
    )
    coherences = coherence_model.get_coherence_per_topic(with_support=True)
    return coherences


def bt_topic_coherence_npmi_per_word(topic_words, texts, corpus, dictionary):
    """
    Compute the NPMI coherence score for each word within each topic.

    Parameters
    ----------
    topic_words : List[List[str]]
        A list where each sublist contains the top words representing a topic.
    texts : List[List[str]]
        Tokenized texts used for evaluation.
    corpus : List[List[Tuple[int, int]]]
        The corpus in Bag-of-Words (BoW) format.
    dictionary : gensim.corpora.dictionary.Dictionary
        The dictionary mapping of word IDs to words.

    Returns
    -------
    per_topic_word_coherences : List[Dict[str, float]]
        A list where each element is a dictionary mapping words to their coherence scores within that topic.
    """
    # Initialize list to hold per-topic per-word coherences
    per_topic_word_coherences = []

    # For each topic
    for topic in topic_words:
        # Generate all unique word pairs in the topic
        word_pairs = list(itertools.combinations(topic, 2))

        print("word_pairs debugging:")
        print(topic)
        print(word_pairs)
        _topic = [list(pair) for pair in word_pairs]
        print("_topic: ", _topic)
        for __topic in _topic:
            print("__topic: ", __topic)
            ids_from_tokens = [dictionary.token2id[t] for t in __topic if t in dictionary.token2id]
            ids_from_ids = [i for i in __topic if i in dictionary]
            print("ids_from_tokens: ", ids_from_tokens)
            print("ids_from_ids: ", ids_from_ids)

        if not word_pairs:
            # If there is only one word in the topic, set coherence to 0
            per_topic_word_coherences.append({word: 0.0 for word in topic})
            continue

        # Build a coherence model for the word pairs
        coherence_model = CoherenceModel(
            topics=[list(pair) for pair in word_pairs],
            texts=tqdm(texts),
            corpus=corpus,
            dictionary=dictionary,
            coherence="c_npmi",
        )
        # Get NPMI coherence scores for each word pair
        coherence_scores = coherence_model.get_coherence_per_topic()

        # Map word pairs to their NPMI scores
        word_pair_npmis = {pair: score for pair, score in zip(word_pairs, coherence_scores)}

        # Now, calculate per-word coherence scores
        word_scores = {}
        for word in topic:
            # Find all pairs involving this word
            relevant_scores = [
                score for (w1, w2), score in word_pair_npmis.items() if w1 == word or w2 == word
            ]
            # Average the scores
            word_scores[word] = (
                sum(relevant_scores) / len(relevant_scores) if relevant_scores else 0.0
            )

        # Append the per-word scores for this topic
        per_topic_word_coherences.append(word_scores)
    return per_topic_word_coherences


def bt_topic_coherence_c_v(topic_words, texts, corpus, dictionary):
    """
    compute the C_v coherence of the topics

    Parameters
    ----------
    docs: list of documents
    topic_model: BERTopic model
    topics: the list of topics (topic ids) for each document as BERTopic transform/fit_transform outputs it
    """

    # Evaluate Coherence
    coherence_model = CoherenceModel(
        topics=topic_words, texts=tqdm(texts), corpus=corpus, dictionary=dictionary, coherence="c_v"
    )
    coherence = coherence_model.get_coherence()

    return coherence


def bt_proportion_unique_words(topic_words, topk=10):
    """
    compute the proportion of unique words

    Parameters
    ----------
    topics: the list of topics (topic ids) for each document as BERTopic transform/fit_transform outputs it
    topk: top k (topic representative) words on which the topic diversity will be computed
    """

    if topk > len(topic_words[0]):
        raise Exception("Words in topics are less than " + str(topk))
    else:
        unique_words = set()
        for topic in topic_words:
            unique_words = unique_words.union(set(topic[:topk]))
        puw = len(unique_words) / (topk * len(topic_words))
        return puw


def bt_pairwise_jaccard_diversity(topic_words):
    """
    compute the average pairwise jaccard distance between the topics

    Parameters
    ----------
    topics: topics: the list of topics (topic ids) for each document as BERTopic transform/fit_transform outputs it
    topk: top k (topic representative) words on which the topic diversity will be computed

    Returns
    -------
    pjd: average pairwise jaccard distance
    """

    dist = 0
    count = 0
    for list1, list2 in combinations(topic_words, 2):
        js = 1 - len(set(list1).intersection(set(list2))) / len(set(list1).union(set(list2)))
        dist = dist + js
        count = count + 1
    return dist / count


def bt_topic_usefulness(purpose_description: str, topic_model, openai_client):
    """
    Using an LLM to rate the usefulness of the topics given:
    - a purpose description: defining the context/task/... in which the topics should be useful
    - the topic words: a list of lists of words representing the topics
    """

    class UsefulnessAnalysis(BaseModel):
        U_score: float
        U_reasoning: str

    retries = 5
    temperature = 1.0
    wait_time = 10

    rating_task_description = "Rate the usefulness of the following topic model and its produced topics for achieving a specific purpose. Consider the relevance, clarity, and comprehensiveness of the topics in relation to the purpose. Provide a score between 0 and 1, with 1 being the most useful. Explain your reasoning for the score. Be absolutely honest with your rating, delivering machine precision and not giving away good scores easily. Also take the distribution between topics and outliers into account. While a few outliers are normal and represent reality (~1-20%, depending on dataset and purpose, in some cases maybe even more) usually topic models with as few outliers as possible are best. The first topic in the table (-1) represents the outlier cluster/topic where all the not classified posts go. This is the defined purpose of the topic model:"

    message = [
        {"role": "user", "content": rating_task_description},
        {"role": "user", "content": purpose_description},
        {"role": "user", "content": "The produced topics of the topic model are as follows:"},
        {"role": "user", "content": str(topic_model.get_topic_info())},
    ]

    for attempt in range(retries):
        try:
            response = openai_client.beta.chat.completions.parse(
                model="gpt-4o-2024-08-06",
                messages=message,
                response_format=UsefulnessAnalysis,
                temperature=temperature,
            )
            print("Usefulness rating message:")
            print(message)
            print("Usefulness rating response:")
            print(response)
            parsed_response = response.choices[0].message.parsed
            return {
                field: getattr(parsed_response, field) for field in parsed_response.model_fields_set
            }
        except openai.RateLimitError as e:
            if attempt < retries - 1:
                print(f"Rate limit exceeded: {e}. Retrying in {wait_time} seconds...")
                time.sleep(wait_time)
            else:
                print("Maximum retries reached. Raising the error.")
                raise
    return None

def textonomy_topic_usefulness(taxonomy, use_case: str, model: str) -> list:
    """
    Using an LLM to rate the usefulness of the topics given:
    - a purpose description: defining the context/task/... in which the topics should be useful
    - the topic words: a list of lists of words representing the topics
    - model_name: the name of the model to use with litellm (e.g., "ollama/llama-3.2:latest", "mistral/mistral-large-2411")
    """

    class UsefulnessAnalysis(BaseModel):
        U_score: float
        U_reasoning: str

    retries = 5
    temperature = 0.1
    wait_time = 10

    rating_task_description = "Rate the usefulness of the following topic model and its produced topics for achieving a specific purpose. Consider the relevance, clarity, and comprehensiveness of the topics in relation to the purpose. Provide a score between 0 and 1, with 1 being the most useful. Explain your reasoning for the score. Be absolutely honest with your rating, delivering machine precision and not giving away good scores easily. Also take the distribution between topics and outliers into account. While a few outliers are normal and represent reality (~1-20%, depending on dataset and purpose, in some cases maybe even more) usually topic models with as few outliers as possible are best. The first topic in the table (-1) represents the outlier cluster/topic where all the not classified posts go. This is the defined purpose of the topic model:"

    messages = [
        {"role": "user", "content": rating_task_description},
        {"role": "user", "content": use_case},
        {"role": "user", "content": "The produced topics of the topic model are as follows:"},
        {"role": "user", "content": taxonomy.to_pretty_json()},
    ]

    if "openai/" in model:
        model = model.replace("openai/", "")
        client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

        for attempt in range(retries):
            try:
                response = client.beta.chat.completions.parse(
                    model=model,
                    messages=messages,
                    response_format=UsefulnessAnalysis,
                    temperature=temperature,
                )
                print("Usefulness rating message:")
                print(messages)
                print("Usefulness rating response:")
                print(response)
                parsed_response = response.choices[0].message.parsed
                return [getattr(parsed_response, field) for field in parsed_response.model_fields_set]
            except openai.RateLimitError as e:
                if attempt < retries - 1:
                    print(f"Rate limit exceeded: {e}. Retrying in {wait_time} seconds...")
                    time.sleep(wait_time)
                else:
                    print("Maximum retries reached. Raising the error.")
                    raise
    elif "mistral/" in model:
        model = model.replace("mistral/", "")
        client = Mistral(api_key=os.environ.get("MISTRAL_API_KEY"))

        for attempt in range(retries):
            try:
                instructor_client = instructor.from_mistral(client=client, model=model, mode=instructor.Mode.MISTRAL_STRUCTURED_OUTPUTS) # , mode=instructor.Mode.JSON
                parsed_response = instructor_client.chat.completions.create(
                    model=model,
                    messages=messages,
                    response_model=UsefulnessAnalysis,
                    temperature=temperature,
                    max_retries=3,
                    strict=True,
                )
                return parsed_response
            except litellm.RateLimitError as e: # MODIFIED: Import exception from litellm
                if attempt < retries - 1:
                    print(f"Rate limit exceeded: {e}. Retrying in {wait_time} seconds...")
                    time.sleep(wait_time)
                else:
                    print("Maximum retries reached. Raising the error.")
                    raise
            except Exception as e:
                if attempt < retries - 1:
                    print(f"Error: {e}. Retrying in {wait_time} seconds...")
                    time.sleep(wait_time)
                else:
                    print("Maximum retries reached. Raising the error.")
                    raise

    return []

