## Calculate all metrics in one go
####


def evaluate_bt_model(
    topic_model, topics, purpose, openai, topk=10, raw_docs=None, preprocessed_docs=None, model_labels=None, gold_labels=None, embeddings=None, topic_words_list=None
):
    """
    Evaluate the quality of topics generated by BERTopic model. Returns a dictionary of metrics.

    Parameters
    ----------
    topic_model: BERTopic model
    raw_docs: list of documents without preprocessing -> a standard preprocessing of lemmatization and stopword removal is applied (like in Röder et al. 2015 "Exploring the space of topic coherence measures")
    topics: the list of topics (topic ids) for each document as BERTopic transform/fit_transform outputs it
    purpose: purpose description for usefulness evaluation by LLM
    openai: OpenAI resource for LLM-based evaluations
    topk: top k (topic representative) words on which the topic diversity will be computed
    preprocessed_docs: list of documents with preprocessing - only use for experimental purposes, e.g. if you are using another language than English
    """
    # TODO: add choice if you want to use preprocessed_docs or raw_docs (like in eval lda model below!)
    # Prepare texts
    if raw_docs:
        pp = preprocessing.TextPreprocessor()
        texts = pp.process_docs(
            raw_docs,
            clean=True,
            clean_html=False,
            tokenize=True,
            lemmatize=True,
            remove_stopwords=True,
            use_bigrams=False,
        )  # TODO: use bigrams here so that evaluation doesn't get worse when using bigrams in the model?
    elif preprocessed_docs:
        texts = preprocessed_docs
    else:
        print("Error: No reference corpus docs provided.")
        return {}

    # Create dictionary and corpus
    dictionary = corpora.Dictionary(texts)
    corpus = [dictionary.doc2bow(token) for token in texts]

    if topic_words_list:
        pp_topic_words = topic_words_list
    else:
        # Prepare topic words
        topic_words = get_topic_words_bertopic(topic_model, topics)
        print("Unprocessed topic words:")
        print(topic_words)

        pp_topic_words = process_topic_words(topic_words, dictionary)
        print("Processed topic words:")
        print(pp_topic_words)
    
    metrics_dict = {
        "C_NPMI": bt_topic_coherence_npmi(pp_topic_words, texts, corpus, dictionary),
        "C_V": bt_topic_coherence_c_v(pp_topic_words, texts, corpus, dictionary),
        "D_PROP_UNI_WORDS": bt_proportion_unique_words(pp_topic_words, topk),
        "D_PAIR_JAC_DIST": bt_pairwise_jaccard_diversity(pp_topic_words),
        "U_LLM_USEFULNESS": bt_topic_usefulness(purpose, topic_model, openai),
        # "NPMI_PER_TOPIC": bt_topic_coherence_npmi_per_topic(
        #     pp_topic_words, texts, corpus, dictionary
        # ),
        # "NPMI_PER_WORD": bt_topic_coherence_npmi_per_word(
        #     pp_topic_words, texts, corpus, dictionary
        # ),
    }
    
    llm_reasoning, metrics_dict["U_score"] = bt_topic_usefulness(purpose_description=purpose, topic_model=topic_model, openai_client=openai)

    if model_labels is not None and gold_labels is not None:
        purity, inverse_purity, harmonic_purity = calculate_purity(y_true=gold_labels, y_pred=model_labels)
        metrics_dict.update(
            {
                "EXT_gold_labels_count": float(len(set(gold_labels))),
                "EXT_P": float(purity),
                "EXT_I_P": float(inverse_purity),
                "EXT_HM_P": float(harmonic_purity),
                "EXT_ARI": float(adjusted_rand_score(labels_true=gold_labels, labels_pred=model_labels)),
                "EXT_NMI": float(normalized_mutual_info_score(
                    labels_true=gold_labels, labels_pred=model_labels
                )),
            }
        )

    if embeddings is not None:
        metrics_dict.update(
            {
                "INT_SILHOUETTE": silhouette_score(X=embeddings, labels=model_labels, metric="cosine"),
                "INT_DAVIES_BOULDIN": davies_bouldin_score(X=embeddings, labels=model_labels),
                "INT_CALINSKI_HARABASZ": calinski_harabasz_score(X=embeddings, labels=model_labels),
            }
        )
    
    return metrics_dict, llm_reasoning

def evaluate_textonomy_model(taxonomy, texts, use_case, model, topic_words):
    """
    Evaluate the quality of topics generated by Textonomy: Topic Coherence, Diversity, and Usefulness.
    Currently only supports already preprocessed documents.
    Returns a dictionary of metrics.
    - texts: preprocessed documents which constitute the reference corpus
    - use_case: purpose description for usefulness evaluation by LLM
    - model_name: the name of the model to use with litellm (e.g., "ollama/gpt-4o", "mistral/mistral-7b")
    """

    # Create dictionary and corpus
    dictionary = corpora.Dictionary(texts)
    corpus = [dictionary.doc2bow(token) for token in texts]

    metrics_dict = {
        "C_NPMI": bt_topic_coherence_npmi(topic_words, texts, corpus, dictionary),
        "C_V": bt_topic_coherence_c_v(topic_words, texts, corpus, dictionary),
        "D_PROP_UNI_WORDS": bt_proportion_unique_words(topic_words),
        "D_PAIR_JAC_DIST": bt_pairwise_jaccard_diversity(topic_words),
    }

    llm_reasoning, metrics_dict["U_score"] = textonomy_topic_usefulness(taxonomy, use_case=use_case, model=model)

    return metrics_dict, llm_reasoning

def evaluate_lda_model(
    lda_model,
    purpose,
    openai_client,
    topk=10,
    ext_cluster_metrics_only=False,
    pp_ref_docs=None,
    raw_ref_docs=None,
    model_labels=None,
    gold_labels=None,
    embeddings=None,
):  # -> tuple[dict[str, Unknown], Unknown]
    """
    Evaluate the quality of topics generated by a gensim LdaModel. Returns a dictionary of metrics.

    Parameters
    ----------
    lda_model: gensim.models.LdaModel or LdaMulticore
    purpose: purpose description for usefulness evaluation
    openai_resource: OpenAI resource for LLM-based evaluations
    topk: top k (topic representative) words on which the topic diversity will be computed
    docs: list of documents with preprocessing already applied
    raw_docs: list of documents without preprocessing -> a standard preprocessing of lemmatization and stopword removal is applied (like in Röder et al. 2015 "Exploring the space of topic coherence measures")
    """
    metrics_dict = {}

    if model_labels is not None and gold_labels is not None:
        purity, inverse_purity, harmonic_purity = calculate_purity(y_true=gold_labels, y_pred=model_labels)
        metrics_dict.update(
            {
                "EXT_gold_labels_count": float(len(set(gold_labels))),
                "EXT_P": float(purity),
                "EXT_I_P": float(inverse_purity),
                "EXT_HM_P": float(harmonic_purity),
                "EXT_ARI": float(adjusted_rand_score(labels_true=gold_labels, labels_pred=model_labels)),
                "EXT_NMI": float(normalized_mutual_info_score(
                    labels_true=gold_labels, labels_pred=model_labels
                )),
            }
        )
    
    if ext_cluster_metrics_only:
        return metrics_dict

    if pp_ref_docs and raw_ref_docs:
        print("Error: Raw and processed reference corpus was provided. Provide only one.")
        return {}
    elif pp_ref_docs:
        print("Preprocssed (reference) docs provided. Using them without further processing.")
        texts = pp_ref_docs
    elif raw_ref_docs:
        # Prepare texts
        print(
            "Raw (reference) docs provided. Preprocessing them with metrics.py internal standard settings."
        )
        pp = preprocessing.TextPreprocessor()
        texts = pp.process_docs(
            raw_ref_docs,
            clean=True,
            clean_html=False,
            tokenize=True,
            lemmatize=True,
            remove_stopwords=True,
            use_bigrams=False,
        )  # TODO: use bigrams here so that evaluation doesn't get worse when using bigrams in the model?
    else:
        print("Error: No reference corpus docs provided.")
        return {}

    # Create dictionary and corpus
    dictionary = corpora.Dictionary(texts)
    corpus = [dictionary.doc2bow(token) for token in texts]

    # Extract topic words
    topic_words = get_top_n_topic_words_lda(lda_model, topk)

    if raw_ref_docs:
        topic_words = process_topic_words(topic_words, dictionary)

    metrics_dict.update(
        {
            "C_NPMI": bt_topic_coherence_npmi(topic_words, texts, corpus, dictionary),
            "C_V": bt_topic_coherence_c_v(topic_words, texts, corpus, dictionary),
            "D_PROP_UNI_WORDS": bt_proportion_unique_words(topic_words, topk),
            "D_PAIR_JAC_DIST": bt_pairwise_jaccard_diversity(topic_words),
        }
    )

    llm_reasoning, metrics_dict["U_LLM_USEFULNESS_SCORE"] = lda_topic_usefulness(
        purpose, lda_model, openai_client=openai_client, topk=topk
    )

    if embeddings is not None:
        metrics_dict.update(
            {
                "INT_SILHOUETTE": silhouette_score(X=embeddings, labels=model_labels, metric="cosine"),
                "INT_DAVIES_BOULDIN": davies_bouldin_score(X=embeddings, labels=model_labels),
                "INT_CALINSKI_HARABASZ": calinski_harabasz_score(X=embeddings, labels=model_labels),
            }
        )

    return metrics_dict, llm_reasoning
